-- Travelo seed data: executed automatically by the MySQL image on the FIRST start
-- (files in /docker-entrypoint-initdb.d run only when the data directory is empty).
-- Column names follow Spring Boot's naming strategy (camelCase -> snake_case).
USE travelo_db;

CREATE TABLE IF NOT EXISTS flight (
  id_flight INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  departure_city VARCHAR(255), departure_airport VARCHAR(255),
  arrival_city VARCHAR(255), arrival_airport VARCHAR(255),
  date DATETIME(6), departure_time TIME(6), arrival_time TIME(6),
  company VARCHAR(255), price DECIMAL(38,2)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS seats (
  id INT NOT NULL PRIMARY KEY,
  id_flight INT UNIQUE,
  a1 VARCHAR(255), b1 VARCHAR(255), c1 VARCHAR(255), d1 VARCHAR(255), a2 VARCHAR(255), b2 VARCHAR(255), c2 VARCHAR(255), d2 VARCHAR(255), a3 VARCHAR(255), b3 VARCHAR(255), c3 VARCHAR(255), d3 VARCHAR(255), a4 VARCHAR(255), b4 VARCHAR(255), c4 VARCHAR(255), d4 VARCHAR(255), a5 VARCHAR(255), b5 VARCHAR(255), c5 VARCHAR(255), d5 VARCHAR(255), a6 VARCHAR(255), b6 VARCHAR(255), c6 VARCHAR(255), d6 VARCHAR(255), a7 VARCHAR(255), b7 VARCHAR(255), c7 VARCHAR(255), d7 VARCHAR(255), a8 VARCHAR(255), b8 VARCHAR(255), c8 VARCHAR(255), d8 VARCHAR(255), a9 VARCHAR(255), b9 VARCHAR(255), c9 VARCHAR(255), d9 VARCHAR(255),
  CONSTRAINT fk_seats_flight FOREIGN KEY (id_flight) REFERENCES flight(id_flight)
) ENGINE=InnoDB;


